namespace MercadoInteligente.Domain;
public enum PriceScope { Unknown, OnlineGeneric, City, Region, FulfillmentRegion, Store, PhysicalVerified }
public enum AvailabilityStatus { Unknown, InStock, OutOfStock, NotSold }
public enum Dimension { Unknown, Mass, Volume, Count, Length }
public enum Freshness { Unknown, Fresh, Stale, Outdated }
public enum SellerKind { Unknown, RetailerDirect, InternalFulfillment, Marketplace }
public enum MatchKind { Candidate, Exact, Substitute, NotEquivalent }
public enum SyncState { Running, Completed, Failed, Aborted }
public enum CapabilityState { Supported, Partial, NotSupported, NotConfigured }
public enum ProductLifecycleState { Unknown, Active, Missing, Inactive, Discontinued }
public enum OptimizationStrategy { MaxSavings, SingleStore, Balanced, MinComplexity }
public class Retailer { public Guid Id { get; set; } = Guid.NewGuid(); public string Code { get; set; } = ""; public string Name { get; set; } = ""; }
public class Store { public Guid Id { get; set; } = Guid.NewGuid(); public Guid RetailerId { get; set; } public Retailer? Retailer { get; set; } public string ExternalId { get; set; } = ""; public string Name { get; set; } = ""; public decimal? Latitude { get; set; } public decimal? Longitude { get; set; } public string VerificationStatus { get; set; } = "UNKNOWN"; }
