public class ExternalSku { public Guid Id { get; set; } = Guid.NewGuid(); public Guid ExternalProductId { get; set; } public string ExternalId { get; set; } = ""; public string? Ean { get; set; } public string Name { get; set; } = ""; public decimal? Quantity { get; set; } public Dimension Dimension { get; set; } public int? PackageCount { get; set; } public decimal? QuantityPerUnit { get; set; } public string? Unit { get; set; } public decimal? TotalQuantity { get; set; } public string? AttributesJson { get; set; } }
public class Seller { public Guid Id { get; set; } = Guid.NewGuid(); public Guid RetailerId { get; set; } public string ExternalId { get; set; } = ""; public string Name { get; set; } = ""; public SellerKind Kind { get; set; } }
public class Offer { public Guid Id { get; set; } = Guid.NewGuid(); public Guid ExternalSkuId { get; set; } public Guid SellerId { get; set; } public Guid? StoreId { get; set; } public decimal Price { get; set; } public decimal? ListPrice { get; set; } public decimal? AvailableQuantityRaw { get; set; } public string Currency { get; set; } = "COP"; public PriceScope Scope { get; set; } public AvailabilityStatus Availability { get; set; } = AvailabilityStatus.Unknown; public string Context { get; set; } = ""; public string? PromotionConditions { get; set; } public DateTime CheckedAt { get; set; } = DateTime.UtcNow; public Guid? RawCaptureId { get; set; } }
public class PriceObservation { public Guid Id { get; set; } = Guid.NewGuid(); public Guid OfferId { get; set; } public decimal Price { get; set; } public decimal? ListPrice { get; set; } public AvailabilityStatus Availability { get; set; } public decimal? AvailableQuantity { get; set; } public string? PromotionConditions { get; set; } public PriceScope? PriceScope { get; set; } public string? PriceContext { get; set; } public Guid? SellerId { get; set; } public Guid? StoreId { get; set; } public DateTime CheckedAt { get; set; } = DateTime.UtcNow; public DateTime ObservedAt { get => CheckedAt; set => CheckedAt = value; } public Guid? RawCaptureId { get; set; } }
public class RawCapture { public Guid Id { get; set; } = Guid.NewGuid(); public string Sha256 { get; set; } = ""; public string RelativePath { get; set; } = ""; public DateTime CapturedAt { get; set; } = DateTime.UtcNow; }
public class CanonicalProduct { public Guid Id { get; set; } = Guid.NewGuid(); public string Name { get; set; } = ""; public string? Brand { get; set; } public string? ImageUrl { get; set; } }
public class ProductVariant { public Guid Id { get; set; } = Guid.NewGuid(); public Guid CanonicalProductId { get; set; } public string? Ean { get; set; } public decimal? Quantity { get; set; } public Dimension Dimension { get; set; } }
public class ProductMatch { public Guid Id { get; set; } = Guid.NewGuid(); public Guid ExternalSkuId { get; set; } public Guid ProductVariantId { get; set; } public MatchKind Kind { get; set; } public string Evidence { get; set; } = ""; }
public class MatchOverride { public Guid Id { get; set; } = Guid.NewGuid(); public Guid ExternalSkuId { get; set; } public Guid ProductVariantId { get; set; } public MatchKind Kind { get; set; } public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public class Basket { public Guid Id { get; set; } = Guid.NewGuid(); public string Name { get; set; } = "Mi mercado"; public decimal? Budget { get; set; } public int? MaxStores { get; set; } public OptimizationStrategy PreferredStrategy { get; set; } = OptimizationStrategy.MaxSavings; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public List<BasketItem> Items { get; set; } = []; }
public class BasketItem { public Guid Id { get; set; } = Guid.NewGuid(); public Guid BasketId { get; set; } public string Query { get; set; } = ""; public decimal Quantity { get; set; } = 1; public Guid? ProductVariantId { get; set; } public Dimension Dimension { get; set; } = Dimension.Unknown; public string? Unit { get; set; } public bool? AllowSubstitutesOverride { get; set; } public int? SizeTolerancePercentOverride { get; set; } public string? PreferredBrand { get; set; } public string? ExcludedBrand { get; set; } public string? Notes { get; set; } }
