public class ComparisonProfile { public Guid Id { get; set; } = Guid.NewGuid(); public string Name { get; set; } = "Default"; public int MaxStores { get; set; } = 2; }
public class SyncRun { public Guid Id { get; set; } = Guid.NewGuid(); public string Provider { get; set; } = ""; public SyncState State { get; set; } = SyncState.Running; public int ItemsReceived { get; set; } public int OffersProcessed { get; set; } public int OffersChanged { get; set; } public int ProductsCreated { get; set; } public int ProductsUpdated { get; set; } public int SkusCreated { get; set; } public int SkusUpdated { get; set; } public int RawNew { get; set; } public int RawDeduplicated { get; set; } public string Context { get; set; } = ""; public string? Trigger { get; set; } public DateTime StartedAt { get; set; } = DateTime.UtcNow; public DateTime? FinishedAt { get; set; } public string? ErrorCode { get; set; } }
public class ProviderHealth { public Guid Id { get; set; } = Guid.NewGuid(); public string Provider { get; set; } = ""; public string Status { get; set; } = "NOT_CONFIGURED"; public DateTime CheckedAt { get; set; } = DateTime.UtcNow; }
public class AppSettings { public int Id { get; set; } = 1; public int MaxStores { get; set; } = 2; public int SizeTolerancePercent { get; set; } = 15; public bool AllowSubstitutes { get; set; } = true; public int MaxOverbuyPercent { get; set; } = 20; public int PriceTtlHours { get; set; } = 6; public int StockTtlHours { get; set; } = 2; public int ProductTtlDays { get; set; } = 7; public int StoresTtlDays { get; set; } = 7; public int RouteTtlHours { get; set; } = 24; public int PromoTtlHours { get; set; } = 4; public int RawRetentionDays { get; set; } = 60; public int LogRetentionDays { get; set; } = 30; public int BackupDailyRetention { get; set; } = 7; public int BackupWeeklyRetention { get; set; } = 4; public int BackupMonthlyRetention { get; set; } = 3; public bool IncludeMarketplace { get; set; } public bool AllowOutdatedOffers { get; set; } public bool AllowUnverifiedLocationsForTravel { get; set; } = false; }
